window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["sanity"]={html:"<div class=\"own-sanity\">\n  <!-- ── NAV ─────────────────────────────────────────────────────────── -->\n  <header class=\"sn-nav\">\n    <a class=\"sn-brand\" href=\"#sn-top\">Northwind</a>\n    <nav class=\"sn-nav-links\" aria-label=\"Primary\">\n      <a href=\"#sn-product\">Product</a>\n      <a href=\"#sn-platform\">Platform</a>\n      <a href=\"#sn-pricing\">Pricing</a>\n      <a href=\"#sn-docs\">Docs</a>\n    </nav>\n    <div class=\"sn-nav-right\">\n      <span class=\"sn-version\">v3.2</span>\n      <a class=\"sn-signin\" href=\"#\">Sign in</a>\n      <a class=\"sn-btn sn-btn-red\" href=\"#sn-pricing\">Start free</a>\n    </div>\n  </header>\n\n  <main id=\"sn-top\">\n    <!-- ── HERO ───────────────────────────────────────────────────────── -->\n    <section class=\"sn-hero\" aria-labelledby=\"sn-h1\">\n      <div class=\"sn-hero-copy\">\n        <p class=\"sn-eyebrow\">Operations platform</p>\n        <h1 id=\"sn-h1\" class=\"sn-display\">Structured operations,<br>end to end.</h1>\n        <p class=\"sn-lead\">Model every dashboard, region, and pipeline as structured content. Northwind keeps your operations data queryable, versioned, and consistent across the floor.</p>\n        <div class=\"sn-hero-cta\">\n          <a class=\"sn-btn sn-btn-red\" href=\"#sn-pricing\">Start building</a>\n          <a class=\"sn-btn sn-btn-dark\" href=\"#sn-product\">See the docs</a>\n        </div>\n        <p class=\"sn-hero-note\"><span class=\"sn-mono\">$</span> npm create northwind@latest</p>\n      </div>\n      <div class=\"sn-hero-frame\" aria-label=\"Sample operations schema\">\n        <div class=\"sn-frame-bar\">\n          <span class=\"sn-dot\"></span><span class=\"sn-dot\"></span><span class=\"sn-dot\"></span>\n          <span class=\"sn-frame-title sn-mono\">metrics.schema</span>\n        </div>\n        <pre class=\"sn-code\"><span class=\"sn-c-key\">type</span> <span class=\"sn-c-name\">Throughput</span> = {\n  <span class=\"sn-c-key\">region</span>: <span class=\"sn-c-str\">'luzon'</span> | <span class=\"sn-c-str\">'visayas'</span> | <span class=\"sn-c-str\">'mindanao'</span>\n  <span class=\"sn-c-key\">units</span>: <span class=\"sn-c-str\">'cases/hr'</span>\n  <span class=\"sn-c-key\">target</span>: <span class=\"sn-c-num\">4200</span>\n  <span class=\"sn-c-key\">actual</span>: <span class=\"sn-c-num\">3987</span>\n}\n\n<span class=\"sn-c-com\">// query the live dataset</span>\n<span class=\"sn-c-name\">client</span>.fetch(<span class=\"sn-c-str\">'*[_type==\"throughput\"]'</span>)</pre>\n      </div>\n    </section>\n\n    <div class=\"sn-ticker\" aria-hidden=\"true\">\n      <div class=\"sn-ticker-track\">\n        <span>SCHEMA-FIRST</span><i></i><span>REAL-TIME APIs</span><i></i><span>VERSIONED CONTENT</span><i></i><span>GLOBAL CDN</span><i></i>\n        <span>SCHEMA-FIRST</span><i></i><span>REAL-TIME APIs</span><i></i><span>VERSIONED CONTENT</span><i></i><span>GLOBAL CDN</span><i></i>\n      </div>\n    </div>\n\n    <!-- ── PLATFORM FEATURES ──────────────────────────────────────────── -->\n    <section id=\"sn-platform\" class=\"sn-section\" aria-labelledby=\"sn-platform-h\">\n      <p class=\"sn-eyebrow\">The platform</p>\n      <h2 id=\"sn-platform-h\" class=\"sn-h2\">One content graph for<br>every operations surface.</h2>\n      <div class=\"sn-grid sn-grid-3\" id=\"snFeatureGrid\"></div>\n    </section>\n\n    <!-- ── PRODUCT FRAME ──────────────────────────────────────────────── -->\n    <section id=\"sn-product\" class=\"sn-section sn-product\" aria-labelledby=\"sn-product-h\">\n      <div class=\"sn-product-head\">\n        <p class=\"sn-eyebrow\">Studio</p>\n        <h2 id=\"sn-product-h\" class=\"sn-h2\">Edit structured data,<br>see it everywhere.</h2>\n        <p class=\"sn-body\">The same fields that power your regional dashboards render as editable content in the Studio. Change the schema, and every consumer updates.</p>\n      </div>\n      <div class=\"sn-product-frame\" aria-label=\"Northwind Studio preview\">\n        <div class=\"sn-studio-side\">\n          <span class=\"sn-studio-logo sn-mono\">NW</span>\n          <ul class=\"sn-studio-nav\">\n            <li class=\"on\"><span class=\"sn-mono\">01</span>Throughput</li>\n            <li><span class=\"sn-mono\">02</span>Regions</li>\n            <li><span class=\"sn-mono\">03</span>Forecast</li>\n            <li><span class=\"sn-mono\">04</span>Alerts</li>\n          </ul>\n        </div>\n        <div class=\"sn-studio-main\">\n          <div class=\"sn-studio-toolbar\">\n            <span class=\"sn-pill\">Published</span>\n            <span class=\"sn-mono sn-faint\">updated 2m ago</span>\n          </div>\n          <div class=\"sn-chart\" aria-hidden=\"true\">\n            <span style=\"--h:62%\"></span><span style=\"--h:78%\"></span><span style=\"--h:54%\"></span><span style=\"--h:88%\"></span><span style=\"--h:71%\"></span><span style=\"--h:96%\"></span><span style=\"--h:83%\"></span>\n          </div>\n          <div class=\"sn-table\">\n            <div class=\"sn-tr sn-tr-head\"><span>Region</span><span>Target</span><span>Actual</span><span>Delta</span></div>\n            <div class=\"sn-tr\"><span>Luzon</span><span>4,200</span><span>3,987</span><span class=\"sn-neg\">-5.1%</span></div>\n            <div class=\"sn-tr\"><span>Visayas</span><span>2,100</span><span>2,244</span><span class=\"sn-pos\">+6.9%</span></div>\n            <div class=\"sn-tr\"><span>Mindanao</span><span>1,650</span><span>1,602</span><span class=\"sn-neg\">-2.9%</span></div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── LOGO WALL ──────────────────────────────────────────────────── -->\n    <section class=\"sn-section sn-logos\" aria-labelledby=\"sn-logos-h\">\n      <p id=\"sn-logos-h\" class=\"sn-eyebrow sn-center\">Trusted on the floor at</p>\n      <div class=\"sn-logo-wall\">\n        <span>ATLAS</span><span>MERIDIAN</span><span>KESTREL</span><span>NORTHFORK</span><span>BLUEPRINT</span><span>HELIOS</span>\n      </div>\n    </section>\n\n    <!-- ── STATS ──────────────────────────────────────────────────────── -->\n    <section class=\"sn-section sn-stats\" aria-label=\"Platform numbers\">\n      <div class=\"sn-stat\"><b>10M+</b><span class=\"sn-mono\">documents served / day</span></div>\n      <div class=\"sn-stat\"><b>42</b><span class=\"sn-mono\">regions live</span></div>\n      <div class=\"sn-stat\"><b>99.99%</b><span class=\"sn-mono\">api uptime</span></div>\n      <div class=\"sn-stat\"><b>&lt;40ms</b><span class=\"sn-mono\">p95 query latency</span></div>\n    </section>\n\n    <!-- ── CTA ────────────────────────────────────────────────────────── -->\n    <section id=\"sn-pricing\" class=\"sn-cta\" aria-labelledby=\"sn-cta-h\">\n      <div class=\"sn-cta-inner\">\n        <div>\n          <p class=\"sn-eyebrow\">Get started</p>\n          <h2 id=\"sn-cta-h\" class=\"sn-h2\">Bring structure<br>to your operations.</h2>\n        </div>\n        <div class=\"sn-cta-actions\">\n          <a class=\"sn-btn sn-btn-red\" href=\"#\">Start free</a>\n          <a class=\"sn-btn sn-btn-dark\" href=\"#sn-docs\">Talk to sales</a>\n          <p class=\"sn-mono sn-faint\">Free while you build &middot; no card required</p>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── FOOTER ─────────────────────────────────────────────────────── -->\n    <footer id=\"sn-docs\" class=\"sn-footer\">\n      <div class=\"sn-foot-brand\">\n        <span class=\"sn-brand\">Northwind</span>\n        <p class=\"sn-body sn-faint\">Structured operations content for teams that live in the terminal.</p>\n      </div>\n      <div class=\"sn-foot-cols\">\n        <div class=\"sn-foot-col\"><h3 class=\"sn-mono\">Product</h3><a href=\"#\">Studio</a><a href=\"#\">Content Lake</a><a href=\"#\">APIs</a></div>\n        <div class=\"sn-foot-col\"><h3 class=\"sn-mono\">Developers</h3><a href=\"#\">Docs</a><a href=\"#\">Reference</a><a href=\"#\">Changelog</a></div>\n        <div class=\"sn-foot-col\"><h3 class=\"sn-mono\">Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Contact</a></div>\n      </div>\n      <div class=\"sn-foot-row\">\n        <span>Sample data — showcase only</span>\n        <span class=\"sn-mono\">© 2026 Northwind</span>\n      </div>\n    </footer>\n  </main>\n</div>\n",css:"/* ══ SANITY — own layout for showcase.html ════════════════════════════════\n   A near-black developer command center: achromatic gray ramp, coral-red pill\n   CTA, electric-blue activation on hover, IBM Plex Mono system labels, and\n   machined negative tracking on display type. Scoped under `.own-sanity`. */\n\n.own-sanity {\n  --canvas: #0b0b0b;\n  --canvas-2: #000000;\n  --surface: #212121;\n  --surface-3: #353535;\n  --line: #212121;\n  --line-strong: #353535;\n  --text: #ffffff;\n  --silver: #b9b9b9;\n  --mute: #797979;\n  --red: #f36458;\n  --blue: #0052ef;\n  --green: #19d600;\n  --mono: 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace;\n\n  --display: 'Space Grotesk', 'Inter', ui-sans-serif, system-ui, sans-serif;\n  --ui: 'Inter', 'Space Grotesk', ui-sans-serif, system-ui, sans-serif;\n\n  --r-xs: 3px;\n  --r-sm: 5px;\n  --r-md: 6px;\n  --r-lg: 12px;\n  --r-pill: 99999px;\n  --gut: clamp(20px, 4cqi, 56px);\n  --sec: clamp(56px, 9cqi, 120px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--canvas);\n  color: var(--text);\n  font-family: var(--ui);\n  font-size: 16px;\n  line-height: 1.5;\n  letter-spacing: -0.18px;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n  overflow-x: clip;\n}\n\n.own-sanity *, .own-sanity *::before, .own-sanity *::after { box-sizing: border-box; }\n.own-sanity :focus-visible { outline: 2px solid var(--blue); outline-offset: 3px; border-radius: 4px; }\n.own-sanity .sn-center { text-align: center; }\n.own-sanity .sn-mono { font-family: var(--mono); letter-spacing: 0; }\n.own-sanity .sn-faint { color: var(--mute); }\n.own-sanity .sn-pos { color: var(--green); }\n.own-sanity .sn-neg { color: var(--red); }\n\n.own-sanity .sn-eyebrow {\n  font-family: var(--mono);\n  font-size: 12px;\n  text-transform: uppercase;\n  letter-spacing: 0.14em;\n  color: var(--mute);\n  margin: 0 0 18px;\n}\n.own-sanity .sn-body { color: var(--silver); font-size: 16px; max-width: 60ch; }\n\n.own-sanity .sn-display {\n  font-family: var(--display);\n  font-weight: 400;\n  font-size: clamp(44px, 8.2cqi, 112px);\n  line-height: 1.0;\n  letter-spacing: -0.045em;\n  margin: 0;\n}\n.own-sanity .sn-h2 {\n  font-family: var(--display);\n  font-weight: 400;\n  font-size: clamp(32px, 4.6cqi, 64px);\n  line-height: 1.06;\n  letter-spacing: -0.035em;\n  margin: 0 0 20px;\n}\n\n/* ── buttons ─────────────────────────────────────────────────────────── */\n.own-sanity .sn-btn {\n  display: inline-flex; align-items: center; justify-content: center;\n  height: 40px; padding: 0 18px;\n  font-family: var(--ui); font-size: 16px; font-weight: 400;\n  border-radius: var(--r-pill);\n  transition: background-color .18s ease, color .18s ease, border-color .18s ease;\n  white-space: nowrap;\n}\n.own-sanity .sn-btn-red { background: var(--red); color: #fff; }\n.own-sanity .sn-btn-red:hover { background: var(--blue); }\n.own-sanity .sn-btn-dark { background: var(--canvas-2); color: var(--silver); }\n.own-sanity .sn-btn-dark:hover { background: var(--blue); color: #fff; }\n\n/* ── nav ─────────────────────────────────────────────────────────────── */\n.own-sanity .sn-nav {\n  position: sticky; top: 68px; z-index: 40;\n  display: flex; align-items: center; gap: 26px;\n  height: 60px; padding: 0 var(--gut);\n  background: rgba(11, 11, 11, .9);\n  backdrop-filter: blur(10px);\n  border-bottom: 1px solid var(--line);\n}\n.own-sanity .sn-brand {\n  font-family: var(--display); font-weight: 500; font-size: 19px;\n  letter-spacing: -0.02em; color: var(--text);\n}\n.own-sanity .sn-nav-links { display: flex; align-items: center; gap: 22px; font-size: 16px; }\n.own-sanity .sn-nav-links a { color: var(--silver); transition: color .18s; }\n.own-sanity .sn-nav-links a:hover { color: var(--blue); }\n.own-sanity .sn-nav-right { margin-left: auto; display: flex; align-items: center; gap: 16px; }\n.own-sanity .sn-version { font-family: var(--mono); font-size: 11px; letter-spacing: 0.1em; color: var(--mute); }\n.own-sanity .sn-signin { font-size: 15px; color: var(--silver); }\n.own-sanity .sn-signin:hover { color: var(--blue); }\n\n/* ── hero ────────────────────────────────────────────────────────────── */\n.own-sanity .sn-hero {\n  display: grid; grid-template-columns: 1.05fr .95fr; gap: clamp(28px, 4cqi, 64px);\n  align-items: center;\n  padding: var(--sec) var(--gut) clamp(48px, 6cqi, 90px);\n}\n.own-sanity .sn-hero-copy { max-width: 560px; }\n.own-sanity .sn-lead { margin: 26px 0 30px; max-width: 46ch; color: var(--silver); font-size: 18px; line-height: 1.5; }\n.own-sanity .sn-hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }\n.own-sanity .sn-hero-note {\n  margin: 26px 0 0; padding: 10px 14px; display: inline-block;\n  font-family: var(--mono); font-size: 13px; color: var(--silver);\n  background: var(--surface); border: 1px solid var(--line-strong); border-radius: var(--r-sm);\n}\n.own-sanity .sn-hero-note .sn-mono { color: var(--green); }\n\n.own-sanity .sn-hero-frame {\n  background: var(--surface); border: 1px solid var(--line-strong);\n  border-radius: var(--r-lg); overflow: hidden;\n}\n.own-sanity .sn-frame-bar {\n  display: flex; align-items: center; gap: 7px;\n  padding: 12px 16px; border-bottom: 1px solid var(--line-strong);\n}\n.own-sanity .sn-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--surface-3); }\n.own-sanity .sn-frame-title { margin-left: 8px; font-size: 12px; color: var(--mute); }\n.own-sanity .sn-code {\n  margin: 0; padding: 22px; font-family: var(--mono); font-size: 13.5px; line-height: 1.75;\n  color: var(--silver); white-space: pre; overflow-x: auto;\n}\n.own-sanity .sn-c-key { color: var(--red); }\n.own-sanity .sn-c-name { color: var(--blue); }\n.own-sanity .sn-c-str { color: var(--green); }\n.own-sanity .sn-c-num { color: #55beff; }\n.own-sanity .sn-c-com { color: var(--mute); }\n\n/* ── ticker ──────────────────────────────────────────────────────────── */\n.own-sanity .sn-ticker {\n  border-top: 1px solid var(--line); border-bottom: 1px solid var(--line);\n  overflow: hidden; background: var(--canvas-2);\n}\n.own-sanity .sn-ticker-track {\n  display: flex; width: max-content; gap: 26px; padding: 14px 0;\n  animation: sn-marq 40s linear infinite;\n}\n.own-sanity .sn-ticker-track span {\n  font-family: var(--mono); font-size: 12px; letter-spacing: 0.18em; color: var(--mute); white-space: nowrap;\n}\n.own-sanity .sn-ticker-track i { width: 5px; height: 5px; border-radius: 50%; background: var(--red); align-self: center; }\n@keyframes sn-marq { to { transform: translateX(-50%); } }\n\n/* ── generic section ─────────────────────────────────────────────────── */\n.own-sanity .sn-section { padding: var(--sec) var(--gut) 0; }\n.own-sanity .sn-section > .sn-eyebrow, .own-sanity .sn-section > .sn-h2, .own-sanity .sn-section > .sn-body { max-width: 760px; }\n\n/* ── feature grid ────────────────────────────────────────────────────── */\n.own-sanity .sn-grid { display: grid; gap: 16px; margin-top: 44px; }\n.own-sanity .sn-grid-3 { grid-template-columns: repeat(3, 1fr); }\n.own-sanity .sn-card {\n  background: var(--surface); border: 1px solid var(--line);\n  border-radius: var(--r-md); padding: 24px;\n  transition: border-color .2s ease, background-color .2s ease;\n}\n.own-sanity .sn-card:hover { border-color: var(--line-strong); }\n.own-sanity .sn-card-tag {\n  font-family: var(--mono); font-size: 11px; text-transform: uppercase; letter-spacing: 0.14em;\n  color: var(--mute); display: block; margin-bottom: 16px;\n}\n.own-sanity .sn-card h3 { font-family: var(--display); font-weight: 425; font-size: 24px; letter-spacing: -0.02em; margin: 0 0 12px; }\n.own-sanity .sn-card p { color: var(--silver); font-size: 15px; margin: 0 0 20px; }\n.own-sanity .sn-card-art {\n  height: 108px; border-radius: var(--r-sm); border: 1px solid var(--line-strong);\n  background: var(--canvas-2); display: grid; place-items: center;\n}\n.own-sanity .sn-card-art svg { width: 62%; height: 62%; }\n\n/* ── product / studio ────────────────────────────────────────────────── */\n.own-sanity .sn-product-head { max-width: 760px; }\n.own-sanity .sn-product-frame {\n  display: grid; grid-template-columns: 220px 1fr; margin-top: 44px;\n  border: 1px solid var(--line-strong); border-radius: var(--r-lg); overflow: hidden;\n  background: var(--surface);\n}\n.own-sanity .sn-studio-side { background: var(--canvas-2); padding: 24px 20px; border-right: 1px solid var(--line-strong); }\n.own-sanity .sn-studio-logo { display: inline-grid; place-items: center; width: 34px; height: 34px; border: 1px solid var(--line-strong); border-radius: var(--r-sm); color: var(--silver); font-size: 12px; }\n.own-sanity .sn-studio-nav { list-style: none; margin: 26px 0 0; padding: 0; display: grid; gap: 4px; }\n.own-sanity .sn-studio-nav li {\n  display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: var(--r-sm);\n  font-size: 14px; color: var(--silver);\n}\n.own-sanity .sn-studio-nav li .sn-mono { font-size: 11px; color: var(--mute); }\n.own-sanity .sn-studio-nav li.on { background: var(--surface-3); color: var(--text); }\n.own-sanity .sn-studio-nav li.on .sn-mono { color: var(--red); }\n.own-sanity .sn-studio-main { padding: 24px; display: grid; gap: 22px; }\n.own-sanity .sn-studio-toolbar { display: flex; align-items: center; justify-content: space-between; }\n.own-sanity .sn-pill {\n  font-family: var(--mono); font-size: 11px; text-transform: uppercase; letter-spacing: 0.1em;\n  background: var(--canvas-2); color: var(--green); border: 1px solid var(--line-strong); border-radius: var(--r-pill); padding: 4px 12px;\n}\n.own-sanity .sn-chart { display: flex; align-items: flex-end; gap: clamp(6px, 1.4cqi, 18px); height: 150px; padding: 12px; background: var(--canvas-2); border: 1px solid var(--line); border-radius: var(--r-md); }\n.own-sanity .sn-chart span { flex: 1; height: var(--h); background: var(--surface-3); border-radius: 3px 3px 0 0; transition: height .6s cubic-bezier(.16,1,.3,1); }\n.own-sanity .sn-chart span:nth-child(6) { background: var(--red); }\n.own-sanity .sn-table { border: 1px solid var(--line); border-radius: var(--r-md); overflow: hidden; font-family: var(--mono); font-size: 13px; }\n.own-sanity .sn-tr { display: grid; grid-template-columns: 1.4fr 1fr 1fr 1fr; padding: 11px 16px; border-bottom: 1px solid var(--line); color: var(--silver); }\n.own-sanity .sn-tr:last-child { border-bottom: none; }\n.own-sanity .sn-tr-head { background: var(--canvas-2); color: var(--mute); text-transform: uppercase; font-size: 11px; letter-spacing: 0.1em; }\n\n/* ── logo wall ───────────────────────────────────────────────────────── */\n.own-sanity .sn-logos { padding-top: var(--sec); }\n.own-sanity .sn-logo-wall {\n  display: flex; flex-wrap: wrap; align-items: center; justify-content: center;\n  gap: clamp(24px, 5cqi, 72px); margin-top: 34px;\n}\n.own-sanity .sn-logo-wall span {\n  font-family: var(--display); font-weight: 500; font-size: clamp(16px, 1.7cqi, 22px);\n  letter-spacing: 0.12em; color: var(--mute); transition: color .2s;\n}\n.own-sanity .sn-logo-wall span:hover { color: var(--silver); }\n\n/* ── stats ───────────────────────────────────────────────────────────── */\n.own-sanity .sn-stats {\n  display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px;\n  padding: var(--sec) var(--gut) 0;\n}\n.own-sanity .sn-stat { border-top: 1px solid var(--line-strong); padding-top: 22px; }\n.own-sanity .sn-stat b { display: block; font-family: var(--display); font-weight: 400; font-size: clamp(32px, 4cqi, 56px); letter-spacing: -0.035em; line-height: 1; }\n.own-sanity .sn-stat span { display: block; margin-top: 10px; font-size: 12px; text-transform: uppercase; color: var(--mute); }\n\n/* ── CTA ─────────────────────────────────────────────────────────────── */\n.own-sanity .sn-cta { margin: var(--sec) var(--gut) 0; }\n.own-sanity .sn-cta-inner {\n  display: grid; grid-template-columns: 1.2fr .8fr; gap: 32px; align-items: end;\n  padding: clamp(32px, 5cqi, 64px); border-radius: var(--r-lg);\n  background: var(--surface); border: 1px solid var(--line-strong);\n}\n.own-sanity .sn-cta-actions { display: flex; flex-direction: column; align-items: flex-start; gap: 14px; }\n.own-sanity .sn-cta-actions .sn-mono { font-size: 12px; }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-sanity .sn-footer {\n  margin-top: var(--sec); padding: clamp(40px, 5cqi, 64px) var(--gut) 32px;\n  border-top: 1px solid var(--line);\n  display: grid; grid-template-columns: 1.4fr 2fr; gap: 40px;\n}\n.own-sanity .sn-foot-brand { max-width: 34ch; }\n.own-sanity .sn-foot-brand .sn-brand { display: inline-block; margin-bottom: 14px; }\n.own-sanity .sn-foot-cols { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-sanity .sn-foot-col { display: flex; flex-direction: column; gap: 12px; }\n.own-sanity .sn-foot-col h3 { margin: 0 0 4px; font-size: 11px; text-transform: uppercase; color: var(--text); font-weight: 500; }\n.own-sanity .sn-foot-col a { color: var(--silver); font-size: 15px; transition: color .18s; }\n.own-sanity .sn-foot-col a:hover { color: var(--blue); }\n.own-sanity .sn-foot-row {\n  grid-column: 1 / -1; display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap;\n  margin-top: 8px; padding-top: 22px; border-top: 1px solid var(--line);\n  font-size: 13px; color: var(--mute);\n}\n\n/* ── reveal on scroll ────────────────────────────────────────────────── */\n.own-sanity .sn-rv { opacity: 0; transform: translateY(24px); transition: opacity .6s ease, transform .7s cubic-bezier(.16,1,.3,1); }\n.own-sanity .sn-rv.sn-in { opacity: 1; transform: none; }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-sanity .sn-hero { grid-template-columns: 1fr; }\n  .own-sanity .sn-hero-frame { order: 2; }\n  .own-sanity .sn-grid-3 { grid-template-columns: 1fr 1fr; }\n  .own-sanity .sn-stats { grid-template-columns: 1fr 1fr; }\n  .own-sanity .sn-cta-inner { grid-template-columns: 1fr; align-items: start; }\n  .own-sanity .sn-footer { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-sanity .sn-nav-links { display: none; }\n  .own-sanity .sn-version { display: none; }\n  .own-sanity .sn-grid-3 { grid-template-columns: 1fr; }\n  .own-sanity .sn-product-frame { grid-template-columns: 1fr; }\n  .own-sanity .sn-studio-side { border-right: none; border-bottom: 1px solid var(--line-strong); }\n  .own-sanity .sn-foot-cols { grid-template-columns: 1fr 1fr; }\n}\n@container frame (max-width: 430px) {\n  .own-sanity .sn-signin { display: none; }\n  .own-sanity .sn-stats { grid-template-columns: 1fr; }\n  .own-sanity .sn-foot-cols { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-sanity *, .own-sanity *::before, .own-sanity *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }\n  .own-sanity .sn-ticker-track { animation: none; }\n  .own-sanity .sn-rv { opacity: 1; transform: none; }\n}\n"};
/* ══ SANITY — own layout behaviour for showcase.html ══════════════════════
   Registers window.OWN_LAYOUTS['sanity'].init(root). Renders the platform
   feature grid from data and reveals cards on scroll. Returns a cleanup fn. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var FEATURES = [
    {
      tag: 'Schema',
      title: 'Model once',
      body: 'Declare your operations entities once. Every dashboard, report, and downstream consumer reads the same structured graph.',
      art: '<svg viewBox="0 0 120 60" fill="none" aria-hidden="true"><rect x="8" y="10" width="30" height="40" rx="3" stroke="#353535"/><rect x="45" y="10" width="30" height="40" rx="3" stroke="#f36458"/><rect x="82" y="10" width="30" height="40" rx="3" stroke="#353535"/><path d="M38 24h7M75 24h7M38 38h7M75 38h7" stroke="#797979"/></svg>'
    },
    {
      tag: 'Realtime',
      title: 'Query live',
      body: 'A CDN-backed query API serves the current state of the floor at sub-40ms p95, with no cache to invalidate by hand.',
      art: '<svg viewBox="0 0 120 60" fill="none" aria-hidden="true"><path d="M6 46 26 30l18 8 20-20 18 12 26-18" stroke="#0052ef" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><circle cx="88" cy="12" r="4" fill="#f36458"/></svg>'
    },
    {
      tag: 'Versioned',
      title: 'Roll back safely',
      body: 'Every edit is a revision. Diff a schema change, preview it against live data, and ship it with an audit trail.',
      art: '<svg viewBox="0 0 120 60" fill="none" aria-hidden="true"><circle cx="20" cy="30" r="7" stroke="#353535"/><circle cx="60" cy="30" r="7" stroke="#f36458"/><circle cx="100" cy="30" r="7" stroke="#353535"/><path d="M27 30h26M67 30h26" stroke="#797979"/></svg>'
    }
  ];

  OWN['sanity'] = {
    init: function (root) {
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;
      var observers = [];
      var rafs = [];

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function raf(fn) { var id = requestAnimationFrame(fn); rafs.push(id); return id; }
      function $(sel) { return root.querySelector(sel); }
      function $$(sel) { return Array.prototype.slice.call(root.querySelectorAll(sel)); }

      function cardHTML(f) {
        return '<article class="sn-card sn-rv">'
          + '<span class="sn-card-tag sn-mono">' + f.tag + '</span>'
          + '<h3>' + f.title + '</h3>'
          + '<p>' + f.body + '</p>'
          + '<div class="sn-card-art">' + f.art + '</div>'
          + '</article>';
      }
      var grid = $('#snFeatureGrid');
      if (grid) grid.innerHTML = FEATURES.map(cardHTML).join('');

      var io = null;
      if (!reduced && typeof IntersectionObserver !== 'undefined') {
        io = new IntersectionObserver(function (ents) {
          ents.forEach(function (en) {
            if (en.isIntersecting) { en.target.classList.add('sn-in'); io.unobserve(en.target); }
          });
        }, { rootMargin: '0px 0px -8% 0px', threshold: 0.08 });
        observers.push(io);
      }
      $$('.sn-rv').forEach(function (el) { if (io) io.observe(el); else el.classList.add('sn-in'); });

      if (!reduced) {
        raf(function () {
          $$('.sn-chart span').forEach(function (s, i) {
            var h = s.style.getPropertyValue('--h');
            s.style.height = '6%';
            raf(function () { setTimeout(function () { if (!disposed) s.style.height = h; }, 60 + i * 60); });
          });
        });
      }

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
        observers.forEach(function (o) { try { o.disconnect(); } catch (e) { /* ignore */ } });
      };
    }
  };
})();
